//预处理程序
bool preProcess(const string fileName, const string newFileName) {
	printTips("开始预处理");
	//打开原始源程序文件
	ifstream in(fileName.c_str());
	if (!in) {
		cout << "源程序文件打开失败：" << fileName << endl;
		return false;
	}
	//将源程序整体读入字符缓冲区，后续清洗阶段在此缓冲区上继续加工
	string code = "";
	char ch;
	while (in.get(ch)) {
		code += ch;
	}
	in.close();

	//第一步：删除注释，支持“//”单行注释和可以跨行的“/* */”块注释，
	//其余字符原样保留，交给后面的空白清洗阶段继续处理
	string noComment = "";
	for (unsigned int i = 0; i < code.length(); i++) {
		if (code[i] == '/' && i + 1 < code.length() && code[i + 1] == '/') {
			//单行注释：一直跳到行尾，换行符本身保留
			i += 2;
			while (i < code.length() && code[i] != '\n') {
				i++;
			}
			if (i < code.length()) {
				noComment += code[i];
			}
		}
		else if (code[i] == '/' && i + 1 < code.length() && code[i + 1] == '*') {
			//块注释：一直跳到配对的“*/”，中途可以跨越任意多行
			i += 2;
			while (i + 1 < code.length() && !(code[i] == '*' && code[i + 1] == '/')) {
				i++;
			}
			i++;//此时i停在“*”上，再前进一位越过“/”，循环的i++负责越过其后
		}
		else {
			noComment += code[i];
		}
	}
	code = noComment;

	//第二步：清洗空白字符，删除回车换行与制表符，并把连续的多个空格压缩成一个
	string cleaned = "";
	for (unsigned int i = 0; i < code.length(); i++) {
		char c = code[i];
		if (c == '\n' || c == '\r' || c == '\t' || c == '\v' || c == '\f') {
			continue;//回车换行、制表符直接丢弃
		}
		if (c == ' ' && !cleaned.empty() && cleaned[cleaned.length() - 1] == ' ') {
			continue;//连续空格只保留第一个
		}
		cleaned += c;
	}
	code = cleaned;

	//将预处理后的源程序以字符流的形式显示出来
	cout << "预处理后的源程序字符流如下：" << endl;
	cout << code << endl << endl;

	//输出到预处理结果文件
	ofstream out(newFileName.c_str());
	if (!out) {
		cout << "预处理结果文件创建失败：" << newFileName << endl;
		return false;
	}
	out << code;
	out.close();
	cout << "预处理结果已保存至：" << newFileName << endl << endl;
	printTips("预处理已完成");
	return true;
}

//判断单词是否是变量名
bool IsIdentifier(const string word) {
	if (word.empty()) {
		return false;
	}
	//首字符只能是字母或者下划线
	if (!isalpha((unsigned char)word[0]) && word[0] != '_') {
		return false;
	}
	//其余字符只能是字母、数字或者下划线
	for (unsigned int i = 1; i < word.length(); i++) {
		if (!isalnum((unsigned char)word[i]) && word[i] != '_') {
			return false;
		}
	}
	return true;
}
//判断单词是否是数字
bool IsNum(const string word) {
	//十进制整数：首位之后的每一个字符都必须是数字
	for (unsigned int i = 1; i < word.length(); i++) {
		if (!isdigit((unsigned char)word[i])) {
			return false;
		}
	}
	return true;
}
//单词-类别对照表，非法单词统一用类别码0表示
static map<string, int> buildWordTypeTable() {
	map<string, int> table;
	table["void"] = 1;
	table["main"] = 2;
	table["int"] = 3;
	table["cout"] = 4;
	table["return"] = 5;
	table["("] = 6;
	table[")"] = 7;
	table["{"] = 8;
	table["}"] = 9;
	table["<<"] = 10;
	table[";"] = 11;
	table[","] = 12;
	table["="] = 13;
	table["*"] = 14;
	table["/"] = 15;
	return table;
}
//判断单词类型
int wtMatch(const string word) {
	static const map<string, int> wordType = buildWordTypeTable();
	//先查关键字与界符运算符表
	map<string, int>::const_iterator it = wordType.find(word);
	if (it != wordType.end()) {
		return it->second;
	}
	//再判断标识符与十进制整数
	if (IsIdentifier(word)) {
		return 16;
	}
	if (IsNum(word)) {
		return 17;
	}
	//都不满足则是非法单词
	return 0;
}
